def can_split_shipments(nums, k):
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    nums = sorted(nums, reverse=True)
    if nums and nums[0] > target:
        return False
    buckets = [0] * k

    def place(i):
        if i == len(nums):
            return True
        seen = set()
        for b in range(k):
            if buckets[b] in seen:
                continue
            seen.add(buckets[b])
            if buckets[b] + nums[i] <= target:
                buckets[b] += nums[i]
                if place(i + 1):
                    return True
                buckets[b] -= nums[i]
            if buckets[b] == 0:
                break
        return False

    return place(0)
